// Dernier épisode 6 Minute English + 5 titres d'actualité en anglais (source du vocabulaire)
const episode = $('BBC 6 Minute English').first().json;
const news = $('BBC News Technology').all().slice(0, 5).map(i => i.json);

const articles = news
  .map(a => `- ${a.title}: ${(a.contentSnippet || '').slice(0, 250)}`)
  .join('\n');

return [{ json: {
  episode: { title: episode.title, link: episode.link || episode.guid || '' },
  articles,
} }];

