// Construit le mail : écoute, vocabulaire, quiz, puis corrections tout en bas
const r = JSON.parse($input.first().json.choices[0].message.content);
const ep = $('Préparer le contenu').first().json.episode;
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

let html = `<h2>Coach TOEIC du jour : ${esc(r.theme)}</h2>`;
html += `<h3>1. Écoute (Parts 1 à 4)</h3><p><a href="${esc(ep.link)}">${esc(ep.title)}</a><br>Écoute une fois sans texte, puis une deuxième fois en notant 3 mots nouveaux.</p>`;
html += `<h3>2. 10 mots du jour</h3><ul>` + r.vocab.map(v =>
  `<li><strong>${esc(v.word)}</strong> : ${esc(v.fr)}<br><em>${esc(v.example)}</em></li>`).join('') + `</ul>`;
html += `<h3>3. Quiz Part 5</h3><ol>` + r.quiz.map(q =>
  `<li>${esc(q.question)}<br>` + q.options.map((o, i) => `(${'ABCD'[i]}) ${esc(o)}`).join(' &nbsp; ') + `</li>`).join('') + `</ol>`;
html += `<p><strong>Astuce :</strong> ${esc(r.tip_fr)}</p>`;
html += `<p>Réponses plus bas. Essaie d'abord !</p>` + '<br>'.repeat(20);
html += `<h3>Corrections</h3><ol>` + r.quiz.map(q =>
  `<li><strong>${esc(q.answer)}</strong> : ${esc(q.explanation_fr)}</li>`).join('') + `</ol>`;

return [{ json: { html, subject: `Coach TOEIC : ${r.theme}` } }];
